using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly HttpClient client;
    private readonly Task<CapturedRequest> captured;
    private readonly TaskCompletionSource<(int Status, string Body)> reply = new();

    private sealed record CapturedRequest(string Method, string Path, string? ContentType, string Body);

    public HttpPaymentGatewayTests()
    {
        var port = GetFreePort();
        var prefix = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(prefix);
        listener.Start();
        client = new HttpClient { BaseAddress = new Uri(prefix) };
        captured = Task.Run(Serve);
    }

    [Fact]
    public async Task Sends_the_authorization_as_a_json_post_with_the_expected_fields()
    {
        reply.SetResult((200, """{"status":"approved"}"""));

        await new HttpPaymentGateway(client).AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        var request = await captured;
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(JsonValueKind.String, root.GetProperty("reference").ValueKind);
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
        Assert.Equal(3, root.EnumerateObject().Count());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        reply.SetResult((200, """{"status":"approved"}"""));

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        reply.SetResult((200, """{"status":"declined"}"""));

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        reply.SetResult((200, """{"id":"auth_1","status":"approved","risk":{"score":3}}"""));

        Assert.Equal(AuthorizationOutcome.Approved, await Authorize());
    }

    [Fact]
    public async Task A_refused_payment_402_is_declined_even_with_an_error_body()
    {
        reply.SetResult((402, """{"error":"card_refused"}"""));

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_402_with_an_empty_body_is_declined()
    {
        reply.SetResult((402, ""));

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failures_are_raised_not_treated_as_a_decision(int status)
    {
        reply.SetResult((status, """{"status":"approved"}"""));

        var error = await Assert.ThrowsAsync<HttpRequestException>(Authorize);
        Assert.Equal((HttpStatusCode)status, error.StatusCode);
    }

    [Fact]
    public async Task A_status_other_than_approved_is_not_approved()
    {
        reply.SetResult((200, """{"status":"pending"}"""));

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task An_answer_without_a_status_is_not_approved()
    {
        reply.SetResult((200, """{"result":"approved"}"""));

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_null_answer_is_not_approved()
    {
        reply.SetResult((200, "null"));

        Assert.Equal(AuthorizationOutcome.Declined, await Authorize());
    }

    [Fact]
    public async Task A_non_json_answer_is_raised()
    {
        reply.SetResult((200, "<html>oops</html>"));

        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
    }

    [Fact]
    public async Task A_status_of_the_wrong_type_is_raised()
    {
        reply.SetResult((200, """{"status":1}"""));

        await Assert.ThrowsAnyAsync<JsonException>(Authorize);
    }

    private Task<AuthorizationOutcome> Authorize() =>
        new HttpPaymentGateway(client).AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

    private async Task<CapturedRequest> Serve()
    {
        var context = await listener.GetContextAsync();
        using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
        var body = await reader.ReadToEndAsync();
        var request = new CapturedRequest(context.Request.HttpMethod, context.Request.Url!.AbsolutePath, context.Request.ContentType, body);

        var (status, answer) = await reply.Task;
        var bytes = Encoding.UTF8.GetBytes(answer);
        context.Response.StatusCode = status;
        context.Response.ContentType = "application/json";
        context.Response.ContentLength64 = bytes.Length;
        await context.Response.OutputStream.WriteAsync(bytes);
        context.Response.Close();
        return request;
    }

    private static int GetFreePort()
    {
        var probe = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        probe.Start();
        var port = ((IPEndPoint)probe.LocalEndpoint).Port;
        probe.Stop();
        return port;
    }

    public void Dispose()
    {
        client.Dispose();
        listener.Close();
    }
}
